/**
 * KnowledgeService
 *
 * Effect.Service for accessing extracted codebase knowledge at runtime.
 * Loads .ai-context/ artifacts generated by scripts/extract-ai-context.ts.
 *
 * Uses Effect.Do and Effect.flatMap patterns for proper TypeScript inference
 * (avoiding Effect.gen yield* which causes downlevelIteration issues).
 */

import { Context, Effect, Layer, Ref, Option } from 'effect'
import { Schema, ParseResult } from 'effect'
import type {
  CodebaseKnowledge,
  SchemaInfo,
  ServiceInfo,
  PatternInfo,
  PatternCategory,
} from '../schemas/knowledge'
import {
  CodebaseKnowledge as CodebaseKnowledgeSchema,
  SchemaInfo as SchemaInfoSchema,
  ServiceInfo as ServiceInfoSchema,
  PatternInfo as PatternInfoSchema,
} from '../schemas/knowledge'

// -----------------------------------------------------------------------------
// Search Result Type
// -----------------------------------------------------------------------------

export interface SearchResult {
  kind: 'schema' | 'service' | 'pattern'
  name: string
  description: string
  relevance: number
  item: SchemaInfo | ServiceInfo | PatternInfo
}

// -----------------------------------------------------------------------------
// Service Interface
// -----------------------------------------------------------------------------

export interface KnowledgeServiceShape {
  /**
   * Load complete codebase knowledge from .ai-context/ artifacts.
   * Caches the result after first load.
   */
  readonly loadContext: Effect.Effect<CodebaseKnowledge>

  /**
   * Get schemas, optionally filtered by namespace (file path contains).
   */
  readonly getSchemas: (
    namespace?: string
  ) => Effect.Effect<readonly SchemaInfo[]>

  /**
   * Get services, optionally filtered by tag prefix.
   */
  readonly getServices: (
    tagPrefix?: string
  ) => Effect.Effect<readonly ServiceInfo[]>

  /**
   * Get patterns, optionally filtered by category.
   */
  readonly getPatterns: (
    category?: PatternCategory
  ) => Effect.Effect<readonly PatternInfo[]>

  /**
   * Search across all knowledge types.
   * Uses simple substring matching (future: semantic embeddings).
   */
  readonly searchSimilar: (
    query: string,
    limit?: number
  ) => Effect.Effect<readonly SearchResult[]>

  /**
   * Force reload from disk (for refresh_codebase_knowledge tool).
   */
  readonly reload: Effect.Effect<void>
}

// -----------------------------------------------------------------------------
// Service Tag
// -----------------------------------------------------------------------------

export class KnowledgeService extends Context.Tag('tmnl/KnowledgeService')<
  KnowledgeService,
  KnowledgeServiceShape
>() {}

// -----------------------------------------------------------------------------
// Helper Functions (Pure)
// -----------------------------------------------------------------------------

/**
 * Simple relevance scoring based on substring matching.
 */
const scoreRelevance = (text: string, query: string): number => {
  const lowerText = text.toLowerCase()
  const lowerQuery = query.toLowerCase()
  const words = lowerQuery.split(/\s+/)

  let score = 0

  // Exact match bonus
  if (lowerText.includes(lowerQuery)) {
    score += 10
  }

  // Word match scoring
  for (const word of words) {
    if (word.length < 2) continue
    if (lowerText.includes(word)) {
      score += 2
    }
  }

  return score
}

/**
 * Search schemas for matches.
 */
const searchSchemas = (
  schemas: readonly SchemaInfo[],
  query: string
): SearchResult[] => {
  const results: SearchResult[] = []
  for (const schema of schemas) {
    const text = `${schema.name} ${schema.description} ${schema.category}`
    const relevance = scoreRelevance(text, query)
    if (relevance > 0) {
      results.push({
        kind: 'schema',
        name: schema.name,
        description: schema.description,
        relevance,
        item: schema,
      })
    }
  }
  return results
}

/**
 * Search services for matches.
 */
const searchServices = (
  services: readonly ServiceInfo[],
  query: string
): SearchResult[] => {
  const results: SearchResult[] = []
  for (const service of services) {
    const text = `${service.name} ${service.description} ${service.capabilities.join(' ')}`
    const relevance = scoreRelevance(text, query)
    if (relevance > 0) {
      results.push({
        kind: 'service',
        name: service.name,
        description: service.description,
        relevance,
        item: service,
      })
    }
  }
  return results
}

/**
 * Search patterns for matches.
 */
const searchPatterns = (
  patterns: readonly PatternInfo[],
  query: string
): SearchResult[] => {
  const results: SearchResult[] = []
  for (const pattern of patterns) {
    const text = `${pattern.name} ${pattern.description} ${pattern.category}`
    const relevance = scoreRelevance(text, query)
    if (relevance > 0) {
      results.push({
        kind: 'pattern',
        name: pattern.name,
        description: pattern.description,
        relevance,
        item: pattern,
      })
    }
  }
  return results
}

// -----------------------------------------------------------------------------
// Live Implementation
// -----------------------------------------------------------------------------

/**
 * Create the Live layer for KnowledgeService.
 *
 * @param contextPath - Path to .ai-context/ directory (relative to CWD)
 */
export const makeKnowledgeServiceLive = (
  contextPath: string = '.ai-context'
): Layer.Layer<KnowledgeService> =>
  Layer.effect(
    KnowledgeService,
    Effect.Do.pipe(
      // Create cache ref for loaded knowledge
      Effect.bind('cacheRef', () =>
        Ref.make<Option.Option<CodebaseKnowledge>>(Option.none())
      ),
      Effect.map(({ cacheRef }) => {
        // Load a single JSON artifact file
        const loadArtifact = <A, I>(
          filename: string,
          schema: Schema.Schema<A, I>
        ): Effect.Effect<A, Error | ParseResult.ParseError> => {
          const fullPath = `${contextPath}/${filename}`

          return Effect.tryPromise({
            try: async () => {
              const fs = await import('node:fs/promises')
              return fs.readFile(fullPath, 'utf-8')
            },
            catch: (error) =>
              new Error(
                `Failed to read ${fullPath}: ${error instanceof Error ? error.message : String(error)}`
              ),
          }).pipe(
            Effect.flatMap((content) =>
              Effect.try({
                try: () => JSON.parse(content) as unknown,
                catch: (error) =>
                  new Error(
                    `Failed to parse ${fullPath}: ${error instanceof Error ? error.message : String(error)}`
                  ),
              })
            ),
            Effect.flatMap((json) => Schema.decodeUnknown(schema)(json))
          )
        }

        // Load all artifacts into CodebaseKnowledge
        const loadAllArtifacts = (): Effect.Effect<CodebaseKnowledge> =>
          Effect.all({
            schemas: loadArtifact(
              'schemas.json',
              Schema.Array(SchemaInfoSchema)
            ).pipe(Effect.orElseSucceed((): readonly SchemaInfo[] => [])),

            services: loadArtifact(
              'services.json',
              Schema.Array(ServiceInfoSchema)
            ).pipe(Effect.orElseSucceed((): readonly ServiceInfo[] => [])),

            patterns: loadArtifact(
              'patterns.json',
              Schema.Array(PatternInfoSchema)
            ).pipe(Effect.orElseSucceed((): readonly PatternInfo[] => [])),

            versionInfo: loadArtifact(
              'version.json',
              Schema.Struct({
                extractedAt: Schema.String,
                version: Schema.String,
              })
            ).pipe(
              Effect.orElseSucceed(() => ({
                extractedAt: new Date().toISOString(),
                version: '0.0.0',
              }))
            ),
          }).pipe(
            Effect.map(
              ({ schemas, services, patterns, versionInfo }): CodebaseKnowledge => ({
                schemas: Array.from(schemas),
                services: Array.from(services),
                patterns: Array.from(patterns),
                extractedAt: new Date(versionInfo.extractedAt),
                version: versionInfo.version,
              })
            )
          )

        // Load context (with caching)
        const loadContext: Effect.Effect<CodebaseKnowledge> = Ref.get(
          cacheRef
        ).pipe(
          Effect.flatMap((cached) => {
            if (Option.isSome(cached)) {
              return Effect.succeed(cached.value)
            }
            return loadAllArtifacts().pipe(
              Effect.tap((knowledge) =>
                Ref.set(cacheRef, Option.some(knowledge))
              )
            )
          })
        )

        return KnowledgeService.of({
          loadContext,

          getSchemas: (namespace) =>
            loadContext.pipe(
              Effect.map((ctx) => {
                if (!namespace) {
                  return ctx.schemas
                }
                return ctx.schemas.filter((s) =>
                  s.file.toLowerCase().includes(namespace.toLowerCase())
                )
              })
            ),

          getServices: (tagPrefix) =>
            loadContext.pipe(
              Effect.map((ctx) => {
                if (!tagPrefix) {
                  return ctx.services
                }
                return ctx.services.filter((s) =>
                  s.tag.toLowerCase().startsWith(tagPrefix.toLowerCase())
                )
              })
            ),

          getPatterns: (category) =>
            loadContext.pipe(
              Effect.map((ctx) => {
                if (!category) {
                  return ctx.patterns
                }
                return ctx.patterns.filter((p) => p.category === category)
              })
            ),

          searchSimilar: (query, limit = 10) =>
            loadContext.pipe(
              Effect.map((ctx) => {
                const schemaResults = searchSchemas(ctx.schemas, query)
                const serviceResults = searchServices(ctx.services, query)
                const patternResults = searchPatterns(ctx.patterns, query)

                const allResults = [
                  ...schemaResults,
                  ...serviceResults,
                  ...patternResults,
                ]

                return allResults
                  .sort((a, b) => b.relevance - a.relevance)
                  .slice(0, limit)
              })
            ),

          reload: Ref.set(cacheRef, Option.none()).pipe(
            Effect.flatMap(() => loadContext),
            Effect.asVoid
          ),
        })
      })
    )
  )

// Default layer with standard path
export const KnowledgeServiceLive = makeKnowledgeServiceLive()
